Section V16.
Variable L : heap_layout.
Variable scfg : SpuriousCfg. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable HI : heap_iface.
Variable lim : Z.
Hypothesis HK : 1 <= hl_k_per_malloc L.
Hypothesis HBO : 2 ^ 20 <= hl_b_overhead L.

Definition hi16 (LB : list (Z * Z)) (cr : credit) (M : word -> option byte) (VM : VmMaps) : Prop :=
  exists cr', hi_heap HI LB cr' M VM /\ fst cr <= fst cr' /\ (bm_on = true \/ snd cr <= snd cr') /\ 0 <= fst cr /\ 0 <= snd cr.
Definition HI16 : heap_iface := {| hi_heap := hi16 |}.

Lemma hi16_intro : forall LB cr M VM, hi_heap HI LB cr M VM -> 0 <= fst cr -> 0 <= snd cr -> hi_heap HI16 LB cr M VM.
Proof.
